def match(t):
    stack=[]; m={}
    for i,c in enumerate(t):
        if c=='(': stack.append(i)
        elif c==')':
            j=stack.pop(); m[j]=i; m[i]=j
    return m
def children_of(t,i,m):
    j=i+1; kids=[]
    while j<m[i]:
        if t[j]=='(':
            kids.append((j,m[j])); j=m[j]+1
        else:
            j+=1
    return kids

